#include <stdio.h>

/* Same enum as the candidate's, plus a count the candidate does not need.
 * Appending STATE_COUNT leaves the other five values unchanged.
 */
enum doc_state { DRAFT, REVIEW, APPROVED, PUBLISHED, ARCHIVED, STATE_COUNT };

static const char *const STATE_NAMES[STATE_COUNT] = {
    "Draft", "Review", "Approved", "Published", "Archived"
};

/* Provided by the candidate in solution.c */
int transition(int state, const char *event);

int main(void)
{
    char event[64];
    int state = DRAFT;

    while (scanf("%63s", event) == 1) {
        int next = transition(state, event);

        if (next < 0) {
            printf("REFUSED\n");
            continue;
        }
        if (next >= STATE_COUNT) {
            printf("INVALID (%d is not a state)\n", next);
            return 1;
        }
        state = next;
        printf("%s\n", STATE_NAMES[state]);
    }
    return 0;
}
